			written = { ["Back to {npc:5875} in the {object:172960}. Use the Glyphs of Summoning on the summoning circle there and defeat the voidwalker to bind it."] = "Back to Gan'rul in the Cleft of Shadow. Use the Glyphs of Summoning on the summoning circle there and defeat the voidwalker to bind it.", ["Follow the road south-west from {area:379} to the {area:380}. {zone:1413} guide starts here."] = "Follow the road south-west from Far Watch Post to the Crossroads. The Barrens guide starts here.", ["Head south through the isles. The Loa idols lie all over the southern isles; {npc:3206} and Hexed Trolls hold them and drop the Hexed Pendants. {quest:826} and Minshina's cage are on the southernmost isle."] = "Head south through the isles. The Loa idols lie all over the southern isles; Voodoo and Hexed Trolls hold them and drop the Hexed Pendants. Zalazane and Minshina's cage are on the southernmost isle.", ["Inside the cave, keep to the right wall all the way round, over the stream: {npc:3183} waits at the end."] = "Inside the cave, keep to the right wall all the way round, over the stream: Yarrog waits at the end.", ["{area:364}"] = "The Den", ["{npc:3193}'s hut stands south of the lizards. The crocolisks along the {area:814} to the west carry {item:4891}."] = "Misha's hut stands south of the lizards. The crocolisks along the Southfury River to the west carry Kron's Amulet.", ["{npc:3203} holds the Burning Blade camp on {area:369}, north-west of {area:362}. Hunters: tame a {npc:3099} with the Taming Rod on the way."] = "Fizzle holds the Burning Blade camp on Thunder Ridge, north-west of Razor Hill. Hunters: tame a Dire Mottled Boar with the Taming Rod on the way.", ["{npc:5887} stands just outside the {area:364}."] = "Canaga stands just outside the Den.", ["{npc:5887} stands outside the {area:364}. {area:639} is the hill just south of it: drink the Earth Sapta there to see the {npc:5891}, then take the Rough Quartz back to {npc:5887}."] = "Canaga stands outside the Den. Spirit Rock is the hill just south of it: drink the Earth Sapta there to see the Minor Manifestation of Earth, then take the Rough Quartz back to Canaga.", ["{zone:1454}'s main gate is just west of {area:817}. {npc:5875} stands in the {object:172960}, the canyon under the {object:172982}."] = "Orgrimmar's main gate is just west of Skull Rock. Gan'rul stands in the Cleft of Shadow, the canyon under the Valley of Strength." },
